// Explorar (#/explorar) — design V3Main + Explorer: LOLA map with numbered sites and three-layer cards
// for the selected site. All values: hourly LOLA + SPICE series (EST, the page's global badge).
// Source of truth: this .tsx file (Preact). explorar.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { Badge, LayerCard, mount } from "../../ds/ui.js";
import { windowMetrics, hourlyRows, type WindowMetrics } from "../data.js";
import { scenarioQuery, scenario, ContextBar, regionMap, seriesFor, seriesProof, pct, hrs, fmtDate, HourStrip, download, setQuery } from "./common.js";

const G = "est"; // global badge of this page (see the provenance strip)

export async function render(outlet: HTMLElement, ctx: RouteCtx): Promise<void> {
  const sc = await scenario(ctx);
  const [{ series, error }] = await seriesFor([sc.site]);
  const w: WindowMetrics = series ? windowMetrics(series, sc.t0, sc.hours) : { status: "NOT_COMPUTED", reason: error };
  const ok = w.status === "COMPUTED";
  const v = (k: "sunPct" | "earthPct" | "longestDarkH" | "longestBlackoutH") => (ok ? w[k] : NaN);

  const map = await regionMap(sc.data.sites, sc.site.id, id => setQuery(ctx, { site: id }));

  const csv = () => {
    const rows = hourlyRows(series!, sc.t0, sc.hours);
    download(sc.site.id + "_" + sc.days + "d.csv", "utc,sun_az_deg,sun_el_deg,sun_margin_deg,earth_az_deg,earth_el_deg,earth_margin_deg\n" + rows.map(r => r.map(x => (typeof x === "number" ? x.toFixed(3) : x)).join(",")).join("\n"), "text/csv");
  };

  mount(outlet, <>
    <div class="page-head">
      <div><p class="lbl-s">Explorar o polo sul</p><h1 data-route-title="">{sc.site.name}</h1></div>
      <ContextBar ctx={ctx} sc={sc} />
    </div>
    {ok ? null : <p class="notice glass-in row" role="status"><Badge kind="nd" />{"Série indisponível para esta janela: " + (w.reason || "N/D")}</p>}
    <div class="split">
      <div class="stack">
        {map}
        <div class="glass card nowcard">
          <span class="lbl-s">{"No início da janela · " + fmtDate(sc.t0)}</span>
          <p class="answer">{ok ? (w.sunUpNow ? "Sol acima do horizonte" : "Sol abaixo do horizonte") : "N/D"}
            {ok && Number.isFinite(w.nextChangeH) ? <span class="t2">{" · muda em " + num(w.nextChangeH, 0, " h")}</span> : null}</p>
        </div>
        <div class="row wrap">
          <button type="button" class="btnG" disabled={series ? undefined : true} onClick={csv}>Baixar CSV horário</button>
          <a class="btnL" href={buildHash("/comparar", { site: sc.site.id, t: ctx.query.t, d: ctx.query.d })}>Comparar com outros locais →</a>
        </div>
      </div>
      <div class="stack">
        <LayerCard title="Luz do Sol" badge={ok ? "est" : "nd"} globalBadge={G}
          answer={<><span class="big">{pct(v("sunPct"))}</span>das horas com o centro do Sol acima do relevo.</>}
          why={<div><p>Conta as horas da janela em que o centro do disco solar fica acima do horizonte do terreno ao redor do local. Mais horas de Sol significam mais energia possível para painéis.</p>
            {series ? <div class="stripes"><div class="s"><span>Sol</span><HourStrip series={series} t0={sc.t0} hours={sc.hours} body="sun" /></div></div> : null}</div>}
          proof={seriesProof(series, sc, [["Definição", "centro do disco acima do horizonte LOLA (sem refração)"],
            ["Ref. PGDA", <><Badge kind="val" />{" " + num(sc.site.pgda_sun_pct, 1, "%") + " (média longa, disco parcial — não comparável 1:1)"}</>]])} />
        <LayerCard title="Contato com a Terra" badge={ok ? "est" : "nd"} globalBadge={G}
          answer={<><span class="big">{pct(v("earthPct"))}</span>{"das horas com a Terra visível. Maior perda seguida: " + hrs(v("longestBlackoutH")) + "."}</>}
          why={<div><p>Visibilidade geométrica do centro da Terra. Não é um enlace de rádio: antena, potência e relé não entram neste número.</p>
            {series ? <div class="stripes"><div class="s"><span>Terra</span><HourStrip series={series} t0={sc.t0} hours={sc.hours} body="earth" /></div></div> : null}</div>}
          proof={seriesProof(series, sc, [["Definição", "centro da Terra acima do horizonte LOLA"], ["Perdas", ok ? num(w.losses, 0) + " na janela" : "N/D"],
            ["Ref. PGDA", <><Badge kind="val" />{" " + num(sc.site.pgda_earth_pct, 1, "%") + " (qualquer parte do disco)"}</>]])} />
        <LayerCard title="Maior noite" badge={ok ? "est" : "nd"} globalBadge={G}
          answer={<><span class="big">{hrs(v("longestDarkH"))}</span>{ok && w.darkStart ? "começando em " + fmtDate(w.darkStart) + "." : "sem noite nesta janela ou N/D."}</>}
          why="A noite mais longa define quanto a bateria precisa guardar. É a sequência mais longa de horas seguidas sem o centro do Sol acima do relevo."
          proof={seriesProof(series, sc, [["Definição", "maior sequência de horas com Sol abaixo do horizonte"], ["Noites", ok ? num(w.nights, 0) : "N/D"]])} />
        <LayerCard title="Energia e bateria" badge="nd" globalBadge={G}
          answer={<><span class="big">N/D</span>Energia não calculada para locais reais nesta versão.</>}
          why="Calcular a bateria exige um modelo de painel, carga e reserva. Hoje esse modelo existe só no painel de bordo, com dados sintéticos (SIM)."
          proof={[["Status", "não calculado"], ["Onde existe", <a href={buildHash("/bordo/energia", {})}>Painel de bordo → Energia (SIM)</a>]]} />
        <LayerCard title="Terreno" badge="est" globalBadge={G}
          answer={<><span class="big">{num(sc.site.site_height_m, 0, " m")}</span>acima da esfera de referência (1.737,4 km).</>}
          why="Altura do relevo LOLA no ponto do catálogo. Declividade e rugosidade aparecem no Terreno 3D."
          proof={[["Coordenadas", num(sc.site.lat, 2, "°") + ", " + num(sc.site.lon, 2, "°")],
            ["Fonte do ponto", sc.site.source_url ? <a href={sc.site.source_url} rel="noopener" target="_blank">{sc.site.source}</a> : sc.site.source],
            ["Nota", sc.data.raw.note], ["3D", <a href={buildHash("/terreno", scenarioQuery(sc))}>Abrir no Terreno 3D</a>]]} />
      </div>
    </div>
  </>);
}
